/**
 * Continental Media — blog authors. Every article is signed by one of
 * these two (assigned randomly but balanced at write time, then saved
 * in that article's front matter — see content/blog/posts/*.md — so it
 * never changes again; this file is just the shared profile data every
 * template reads by slug).
 *
 * Bios are verbatim as given by the user — never paraphrase them.
 * Photo paths point at the circular WebP avatars generated by
 * scripts/blog/generate-avatars.py. "team" links to the Nosotros page
 * (public/nosotros.html), per the user's own "a la página de equipo o
 * «Nosotros»" phrasing — both options named, simplest one taken.
 */

export const AUTHORS = {
  'rafael-aguirre': {
    slug: 'rafael-aguirre',
    nombre: 'Rafael Aguirre',
    rol: 'Fundador y Director General',
    bio: 'Fundador y director de Continental Media. Más de 25 años de experiencia en marketing digital y comunicación, ayudando a marcas a conectar con sus audiencias en cada etapa de su crecimiento.',
    avatar: 'assets/images/blog/authors/rafael-aguirre.webp',
    teamUrl: 'nosotros.html',
  },
  'pepe-bermudez': {
    slug: 'pepe-bermudez',
    nombre: 'Pepe Bermúdez',
    rol: 'Director Querétaro',
    bio: 'Fundador de Publifix. Construyó una de las plataformas SaaS más reconocidas en Latinoamérica para relaciones públicas, social listening y análisis de audiencias con IA.',
    avatar: 'assets/images/blog/authors/pepe-bermudez.webp',
    teamUrl: 'nosotros.html',
  },
};

export function authorBySlug(slug) {
  return AUTHORS[slug] || null;
}

/**
 * Deterministic, order-independent "random but balanced" author pick
 * for a given backlog post ID: hashes the ID to get a reproducible
 * coin flip, then nudges toward whichever author currently has fewer
 * assigned posts among `existingAssignments` (an array of author
 * slugs already committed in front matter) so the split stays close
 * to 50/50 over the full 100-post run. Only ever consulted the first
 * time a post is written; once saved in front matter, that value is
 * the source of truth forever after and this function is never
 * called again for that post.
 */
export function pickAuthorSlug(postId, existingAssignments = []) {
  const slugs = Object.keys(AUTHORS);
  const counts = Object.fromEntries(slugs.map((s) => [s, 0]));
  for (const s of existingAssignments) {
    if (counts[s] !== undefined) counts[s]++;
  }
  const diff = counts[slugs[0]] - counts[slugs[1]];
  if (diff > 0) return slugs[1];
  if (diff < 0) return slugs[0];

  let hash = 0;
  for (const ch of String(postId)) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
  return slugs[hash % slugs.length];
}
